#!/usr/bin/env node
"use strict";

/**
 * MCP acceptance harness — Phase 0.4 security & isolation baseline.
 *
 * A standalone black-box harness that targets a configurable production-component
 * MCP endpoint and asserts the fail-closed security and concurrency-isolation
 * contract:
 *
 *   S1  wrong-issuer token fails closed (401 + public WWW-Authenticate);
 *   S2  wrong-audience token fails closed (401 + public WWW-Authenticate);
 *   S3  wrong-signature token fails closed (401 + public WWW-Authenticate);
 *   S4  expired token fails closed (401 + public WWW-Authenticate);
 *   S5  wrong-client token fails closed (401 + public WWW-Authenticate);
 *   S6  missing grant denies calendar_list without disclosing calendars;
 *   S7  revoked grant denies calendar_list without disclosing calendars;
 *   S8  broadened grant denies calendar_list without disclosing unauthorized
 *       calendars;
 *   S9  two concurrent authenticated clients cannot observe each other's
 *       identity, calendars, session, or grant state.
 *
 * Baseline expectation (Phase 0.4): against the current production component,
 * S1-S9 FAIL because the authorization service is not deployed and the MCP
 * gateway does not implement the MCP lifecycle or token validation. The harness
 * asserts the target contract and therefore exits non-zero against the current
 * production component. That failure is the intentional, asserted exit condition
 * for this phase: it documents the current broken state that later phases must
 * fix. The harness is a regression gate: it stays red until the production
 * component implements fail-closed token validation, grant enforcement, and
 * concurrency isolation.
 *
 * This harness does NOT launch or depend on the slice1-lab binaries, and it
 * does NOT treat the lab binary as a release artifact. It reuses the
 * slice1-lab fixture shapes (negative-token / fail-closed cases from
 * slice1-lab/negative_tests.py cases 3-9, slice1-lab/PROOF.md P7) and the
 * MCP/OAuth standards-compliance expectations. It is a pure HTTP client: it
 * starts no servers and leaves no processes behind.
 *
 * Configuration (command-line flags, then environment variables, then defaults):
 *   --url / MCP_URL             MCP endpoint URL (default: https://mcal.hajnal.space/mcp)
 *   --issuer / MCP_OAUTH_ISSUER configured authorization-server issuer
 *                               (default: https://cal.hajnal.space)
 *   --redirect / MCP_REDIRECT   admitted loopback redirect URI
 *                               (default: http://127.0.0.1:8765/callback)
 *   --timeout-ms / MCP_TIMEOUT_MS              request timeout ms (default: 15000)
 *   --record-dir / MCP_RECORD_DIR              record directory (default: OS temp dir)
 *
 * Exit codes:
 *   0  all security/isolation assertions pass (PASS)
 *   1  one or more security/isolation assertions fail (FAIL) — the intentional
 *      Phase 0.4 baseline exit condition against the current production component
 *   2  harness error (invalid configuration, network failure, unexpected error)
 */

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const {
  SCOPE_CATALOG,
  isPlainObject,
  decodeJwtPayload,
  tamperJwtPayload,
  tamperJwtSignature,
  httpProbe,
  runOAuthFlow,
  mcpCall,
  deterministicStringify,
} = require("./lib");

const HARNESS_NAME = "commoncal-mcp-acceptance";
const HARNESS_VERSION = "0.4.0";

const DEFAULTS = {
  url: "https://mcal.hajnal.space/mcp",
  issuer: "https://cal.hajnal.space",
  redirect: "http://127.0.0.1:8765/callback",
  timeoutMs: 15000,
};

class HarnessError extends Error {}

function env(name, fallback) {
  const v = process.env[name];
  return v === undefined || v === "" ? fallback : v;
}

function parseArgs(argv) {
  const flags = {};
  const unknown = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") {
      flags.help = true;
      continue;
    }
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      let name;
      let value;
      if (eq !== -1) {
        name = arg.slice(2, eq);
        value = arg.slice(eq + 1);
      } else {
        name = arg.slice(2);
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("--")) {
          value = next;
          i++;
        } else {
          value = "true";
        }
      }
      flags[name] = value;
    } else {
      unknown.push(arg);
    }
  }
  flags._unknown = unknown;
  return flags;
}

function printHelp() {
  console.log(`Usage: node mcp-acceptance/security-isolation.js [options]

Options:
  --url <url>              MCP endpoint URL (default: ${DEFAULTS.url})
  --issuer <url>           configured authorization-server issuer (default: ${DEFAULTS.issuer})
  --redirect <url>         admitted loopback redirect URI (default: ${DEFAULTS.redirect})
  --timeout-ms <n>         request timeout in ms (default: ${DEFAULTS.timeoutMs})
  --record-dir <dir>       directory for the deterministic record (default: OS temp dir)
  -h, --help               show this help

Environment variables MCP_URL, MCP_OAUTH_ISSUER, MCP_REDIRECT, MCP_TIMEOUT_MS,
and MCP_RECORD_DIR are also honored; command-line flags take precedence.
`);
}

function describeError(err) {
  if (err === undefined || err === null) return "unknown error";
  if (typeof err === "string") return err;
  return err.message || String(err);
}

function resolve(flags, flagName, envName, fallback) {
  if (flags[flagName] !== undefined) return flags[flagName];
  return env(envName, fallback);
}

function loadConfig(flags) {
  const url = resolve(flags, "url", "MCP_URL", DEFAULTS.url);
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new HarnessError(`MCP_URL is not a valid URL: ${url}`);
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new HarnessError(`MCP_URL must use http or https: ${url}`);
  }

  const issuer = resolve(flags, "issuer", "MCP_OAUTH_ISSUER", DEFAULTS.issuer);
  let issuerParsed;
  try {
    issuerParsed = new URL(issuer);
  } catch {
    throw new HarnessError(`MCP_OAUTH_ISSUER is not a valid URL: ${issuer}`);
  }
  if (issuerParsed.protocol !== "http:" && issuerParsed.protocol !== "https:") {
    throw new HarnessError(`MCP_OAUTH_ISSUER must use http or https: ${issuer}`);
  }

  const redirect = resolve(flags, "redirect", "MCP_REDIRECT", DEFAULTS.redirect);
  let redirectParsed;
  try {
    redirectParsed = new URL(redirect);
  } catch {
    throw new HarnessError(`MCP_REDIRECT is not a valid URL: ${redirect}`);
  }

  const timeoutRaw = resolve(flags, "timeout-ms", "MCP_TIMEOUT_MS", String(DEFAULTS.timeoutMs));
  const timeoutMs = Number(timeoutRaw);
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    throw new HarnessError(`MCP_TIMEOUT_MS must be a positive number: ${timeoutRaw}`);
  }

  return {
    url,
    issuer,
    redirect,
    timeoutMs,
    recordDir: resolve(flags, "record-dir", "MCP_RECORD_DIR", os.tmpdir()),
  };
}

// ---------------------------------------------------------------------------
// Test hooks (verification-only; not part of the production contract)
// ---------------------------------------------------------------------------

/**
 * Mint a token with specific claims using the mock's `/_test/token/mint` hook.
 * This is a verification-only helper; it is only available when the harness is
 * run against the mock server (not against a real production component).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {object} claims  The claims to embed in the token.
 * @returns {Promise<string|null>} The minted token, or null on failure.
 */
async function mintToken(cfg, issuer, claims) {
  const url = `${issuer.replace(/\/$/, "")}/_test/token/mint`;
  try {
    const resp = await httpProbe(cfg, "POST", url, { claims });
    if (resp.status === 200 && isPlainObject(resp.bodyJson) && resp.bodyJson.access_token) {
      return resp.bodyJson.access_token;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Drive a grant-state test hook (revoke / broaden / reset / delete).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} hook  The hook name (revoke / broaden / reset / delete).
 * @param {object} body  The hook body.
 * @returns {Promise<boolean>} True if the hook succeeded.
 */
async function grantHook(cfg, issuer, hook, body) {
  const url = `${issuer.replace(/\/$/, "")}/_test/grant/${hook}`;
  try {
    const resp = await httpProbe(cfg, "POST", url, body);
    return resp.status === 200;
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// Assertions
// ---------------------------------------------------------------------------

/**
 * Assert that a tools/call calendar_list response fails closed (401 with a
 * public WWW-Authenticate challenge, or a JSON-RPC error with no calendar
 * data leaked).
 */
function assertFailClosed(resp, label) {
  const violations = [];

  // The response must NOT be a successful calendar_list (200 with content).
  if (resp.status === 200 && isPlainObject(resp.bodyJson) && resp.bodyJson.result) {
    const result = resp.bodyJson.result;
    if (Array.isArray(result.content) && result.content.length > 0) {
      violations.push(
        `${label}: calendar_list returned a successful result with content; expected fail-closed denial`
      );
    }
  }

  // If the response is 401, it must carry a public WWW-Authenticate challenge.
  if (resp.status === 401) {
    const www = resp.headers["www-authenticate"];
    if (www === undefined) {
      violations.push(
        `${label}: 401 response has no WWW-Authenticate header; expected a Bearer challenge`
      );
    } else if (!/^Bearer\s/i.test(www)) {
      violations.push(
        `${label}: WWW-Authenticate is not a Bearer challenge: ${JSON.stringify(www)}`
      );
    }
  }

  return violations;
}

/**
 * Assert that a tools/call calendar_list response denies without disclosing
 * unauthorized calendars (no calendar data in the response body).
 */
function assertNoCalendarLeak(resp, label) {
  const violations = [];
  if (resp.bodyRaw && resp.bodyRaw.length > 0) {
    // Check that the response body does not contain calendar data.
    // A successful calendar_list would contain "calendars" or calendar ids.
    if (resp.bodyRaw.includes('"calendars"') || resp.bodyRaw.includes('"calendar_id"')) {
      violations.push(
        `${label}: response body appears to disclose calendar data; expected no leak`
      );
    }
  }
  return violations;
}

/**
 * Assert that a tools/call calendar_list response does not disclose
 * unauthorized calendar IDs (the broadened-grant case). The response may
 * contain authorized calendars, but must NOT contain the unauthorized ones.
 */
function assertNoUnauthorizedCalendars(resp, label, unauthorizedIds) {
  const violations = [];
  const calendars = extractCalendars(resp);
  if (calendars === null) {
    // No calendars in the response; nothing to check.
    return violations;
  }
  const ids = new Set(calendars.map((c) => c.id));
  const leaked = unauthorizedIds.filter((id) => ids.has(id));
  if (leaked.length > 0) {
    violations.push(
      `${label}: response discloses unauthorized calendar ids ${JSON.stringify(leaked)}`
    );
  }
  return violations;
}

/**
 * S9: two concurrent authenticated clients cannot observe each other's
 * identity, calendars, session, or grant state.
 */
function assertIsolation(clientA, clientB) {
  const violations = [];

  // Both clients should have succeeded (200) with their own calendars.
  if (clientA.status !== 200) {
    violations.push(
      `S9: client A calendar_list returned HTTP ${clientA.status}; expected 200`
    );
  }
  if (clientB.status !== 200) {
    violations.push(
      `S9: client B calendar_list returned HTTP ${clientB.status}; expected 200`
    );
  }

  // Extract the calendars from each client's response.
  const calendarsA = extractCalendars(clientA);
  const calendarsB = extractCalendars(clientB);

  if (calendarsA === null || calendarsB === null) {
    // If we can't extract calendars, we can't assert isolation.
    return violations;
  }

  // The two clients should have DIFFERENT calendars (different subjects).
  const idsA = new Set(calendarsA.map((c) => c.id));
  const idsB = new Set(calendarsB.map((c) => c.id));

  // Check for overlap: if any calendar id appears in both, that's a leak.
  const overlap = [...idsA].filter((id) => idsB.has(id));
  if (overlap.length > 0) {
    violations.push(
      `S9: clients A and B share calendar ids ${JSON.stringify(overlap)}; expected no overlap`
    );
  }

  return violations;
}

/**
 * Extract the calendar list from a tools/call response. Returns an array of
 * calendar objects, or null if the response does not contain a calendar list.
 */
function extractCalendars(resp) {
  if (!isPlainObject(resp.bodyJson) || !resp.bodyJson.result) return null;
  const result = resp.bodyJson.result;
  if (!Array.isArray(result.content) || result.content.length === 0) return null;
  const content = result.content[0];
  if (!content || typeof content.text !== "string") return null;
  try {
    const parsed = JSON.parse(content.text);
    if (isPlainObject(parsed) && Array.isArray(parsed.calendars)) {
      return parsed.calendars;
    }
    return null;
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Record
// ---------------------------------------------------------------------------

function writeRecord(cfg, record) {
  fs.mkdirSync(cfg.recordDir, { recursive: true });
  const recordPath = path.join(cfg.recordDir, "mcp-acceptance-security-isolation.json");
  const envelope = {
    harness: HARNESS_NAME,
    harnessVersion: HARNESS_VERSION,
    phase: "0.4-security-isolation",
    target: cfg.url,
    issuer: cfg.issuer,
    redirect: cfg.redirect,
    recordedBy: "security-isolation-probe",
    record,
  };
  fs.writeFileSync(recordPath, deterministicStringify(envelope) + "\n", "utf8");
  return recordPath;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  const flags = parseArgs(process.argv.slice(2));

  if (flags.help) {
    printHelp();
    return 0;
  }

  if (flags._unknown.length > 0) {
    console.error(
      `[mcp-acceptance] CONFIG ERROR: unknown argument(s): ${flags._unknown.join(", ")}`
    );
    console.error("[mcp-acceptance] Run with --help for usage.");
    return 2;
  }

  let cfg;
  try {
    cfg = loadConfig(flags);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] CONFIG ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }

  console.log(`[mcp-acceptance] target: ${cfg.url}`);
  console.log(`[mcp-acceptance] issuer: ${cfg.issuer}`);
  console.log(`[mcp-acceptance] redirect: ${cfg.redirect}`);

  const record = {
    assertions: {},
  };

  // First, run the OAuth flow to get a valid token (for the negative cases).
  let flow;
  try {
    flow = await runOAuthFlow(cfg, cfg.issuer, cfg.redirect);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.oauthFlow = flow.record;

  // If the OAuth flow failed, we cannot proceed to the security cases.
  if (!flow.accessToken) {
    const allViolations = [
      "S0: OAuth flow did not complete; cannot drive security cases",
    ];
    let recordPath = null;
    try {
      recordPath = writeRecord(cfg, record);
    } catch (err) {
      console.error(
        `[mcp-acceptance] WARNING: could not write record: ${describeError(err)}`
      );
    }
    console.log("");
    console.log("[mcp-acceptance] FAIL: OAuth flow did not complete");
    for (const v of allViolations) {
      console.log(`  - ${v}`);
    }
    if (recordPath) {
      console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
    }
    console.log("");
    console.log(
      "[mcp-acceptance] This failure is the intentional Phase 0.4 baseline exit"
    );
    console.log(
      "[mcp-acceptance] condition: the current production component does not"
    );
    console.log(
      "[mcp-acceptance] deploy the authorization service or implement the MCP"
    );
    console.log(
      "[mcp-acceptance] lifecycle."
    );
    return 1;
  }

  const validToken = flow.accessToken;
  const clientId = flow.clientId;
  const sub = "1"; // The fixed lab subject.

  // -----------------------------------------------------------------------
  // S1-S5: Negative token cases
  // -----------------------------------------------------------------------

  // S1: wrong issuer.
  let s1Token = await mintToken(cfg, cfg.issuer, { iss: "http://evil.example.com" });
  if (!s1Token) {
    s1Token = tamperJwtPayload(validToken, { iss: "http://evil.example.com" });
  }
  let s1Resp;
  try {
    s1Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 101, s1Token);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s1 = s1Resp;
  const s1 = assertFailClosed(s1Resp, "S1 (wrong issuer)");
  record.assertions.S1 = { pass: s1.length === 0, violations: s1 };

  // S2: wrong audience.
  let s2Token = await mintToken(cfg, cfg.issuer, { aud: "http://evil.example.com/mcp" });
  if (!s2Token) {
    s2Token = tamperJwtPayload(validToken, { aud: "http://evil.example.com/mcp" });
  }
  let s2Resp;
  try {
    s2Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 102, s2Token);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s2 = s2Resp;
  const s2 = assertFailClosed(s2Resp, "S2 (wrong audience)");
  record.assertions.S2 = { pass: s2.length === 0, violations: s2 };

  // S3: wrong signature.
  const s3Token = tamperJwtSignature(validToken);
  let s3Resp;
  try {
    s3Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 103, s3Token);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s3 = s3Resp;
  const s3 = assertFailClosed(s3Resp, "S3 (wrong signature)");
  record.assertions.S3 = { pass: s3.length === 0, violations: s3 };

  // S4: expired token.
  const now = Math.floor(Date.now() / 1000);
  let s4Token = await mintToken(cfg, cfg.issuer, { exp: now - 3600, iat: now - 7200 });
  if (!s4Token) {
    s4Token = tamperJwtPayload(validToken, { exp: now - 3600, iat: now - 7200 });
  }
  let s4Resp;
  try {
    s4Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 104, s4Token);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s4 = s4Resp;
  const s4 = assertFailClosed(s4Resp, "S4 (expired token)");
  record.assertions.S4 = { pass: s4.length === 0, violations: s4 };

  // S5: wrong client.
  let s5Token = await mintToken(cfg, cfg.issuer, { client_id: "unknown-client" });
  if (!s5Token) {
    s5Token = tamperJwtPayload(validToken, { client_id: "unknown-client" });
  }
  let s5Resp;
  try {
    s5Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 105, s5Token);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s5 = s5Resp;
  const s5 = assertFailClosed(s5Resp, "S5 (wrong client)");
  record.assertions.S5 = { pass: s5.length === 0, violations: s5 };

  // -----------------------------------------------------------------------
  // S6-S8: Grant cases
  // -----------------------------------------------------------------------

  // S6: missing grant.
  await grantHook(cfg, cfg.issuer, "delete", { sub, client_id: clientId });
  let s6Resp;
  try {
    s6Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 106, validToken);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s6 = s6Resp;
  const s6 = [...assertFailClosed(s6Resp, "S6 (missing grant)"), ...assertNoCalendarLeak(s6Resp, "S6 (missing grant)")];
  record.assertions.S6 = { pass: s6.length === 0, violations: s6 };

  // S7: revoked grant.
  await grantHook(cfg, cfg.issuer, "reset", { sub, client_id: clientId });
  await grantHook(cfg, cfg.issuer, "revoke", { sub, client_id: clientId });
  let s7Resp;
  try {
    s7Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 107, validToken);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s7 = s7Resp;
  const s7 = [...assertFailClosed(s7Resp, "S7 (revoked grant)"), ...assertNoCalendarLeak(s7Resp, "S7 (revoked grant)")];
  record.assertions.S7 = { pass: s7.length === 0, violations: s7 };

  // S8: broadened grant. The grant is broadened to include unauthorized
  // calendar IDs (999/998). The resource server must NOT disclose these
  // unauthorized calendars. It may return the authorized calendars (101/102),
  // but must not return 999/998.
  await grantHook(cfg, cfg.issuer, "broaden", { sub, client_id: clientId });
  let s8Resp;
  try {
    s8Resp = await mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 108, validToken);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.s8 = s8Resp;
  const s8 = assertNoUnauthorizedCalendars(s8Resp, "S8 (broadened grant)", [999, 998]);
  record.assertions.S8 = { pass: s8.length === 0, violations: s8 };

  // Reset the grant for the isolation test.
  await grantHook(cfg, cfg.issuer, "reset", { sub, client_id: clientId });

  // -----------------------------------------------------------------------
  // S9: Concurrency isolation
  // -----------------------------------------------------------------------

  // Run two concurrent authenticated clients with DIFFERENT subjects. The
  // mock supports two subjects (sub=1 "Alice" with calendars 101/102, and
  // sub=2 "Bob" with calendars 201/202). We mint tokens for each subject and
  // set up grants for each, then run them concurrently and assert they do not
  // observe each other's calendars.
  const tokenA = await mintToken(cfg, cfg.issuer, { sub: "1" });
  const tokenB = await mintToken(cfg, cfg.issuer, { sub: "2" });

  // Set up grants for both subjects with their own calendars.
  await grantHook(cfg, cfg.issuer, "set", { sub: "1", client_id: clientId, allowed_calendar_ids: [101, 102] });
  await grantHook(cfg, cfg.issuer, "set", { sub: "2", client_id: clientId, allowed_calendar_ids: [201, 202] });

  const [clientA, clientB] = await Promise.all([
    mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 201, tokenA || validToken),
    mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 202, tokenB || validToken),
  ]);
  record.s9 = { clientA, clientB };
  const s9 = assertIsolation(clientA, clientB);
  record.assertions.S9 = { pass: s9.length === 0, violations: s9 };

  let recordPath = null;
  try {
    recordPath = writeRecord(cfg, record);
  } catch (err) {
    console.error(
      `[mcp-acceptance] WARNING: could not write record: ${describeError(err)}`
    );
  }

  const allViolations = [...s1, ...s2, ...s3, ...s4, ...s5, ...s6, ...s7, ...s8, ...s9];
  for (const [id, list] of [
    ["S1", s1],
    ["S2", s2],
    ["S3", s3],
    ["S4", s4],
    ["S5", s5],
    ["S6", s6],
    ["S7", s7],
    ["S8", s8],
    ["S9", s9],
  ]) {
    if (list.length === 0) {
      console.log(`[mcp-acceptance] ${id}: PASS`);
    }
  }

  if (allViolations.length > 0) {
    console.log("");
    console.log("[mcp-acceptance] FAIL: security/isolation is NOT compliant");
    for (const v of allViolations) {
      console.log(`  - ${v}`);
    }
    if (recordPath) {
      console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
    }
    console.log("");
    console.log(
      "[mcp-acceptance] This failure is the intentional Phase 0.4 baseline exit"
    );
    console.log(
      "[mcp-acceptance] condition: the current production component does not"
    );
    console.log(
      "[mcp-acceptance] implement fail-closed token validation, grant"
    );
    console.log(
      "[mcp-acceptance] enforcement, and concurrency isolation."
    );
    return 1;
  }

  console.log("");
  console.log("[mcp-acceptance] PASS: security/isolation are compliant");
  if (recordPath) {
    console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
  }
  return 0;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[mcp-acceptance] UNEXPECTED ERROR: ${describeError(err)}`);
    if (err && err.stack) {
      console.error(err.stack);
    }
    process.exitCode = 2;
  });

#!/usr/bin/env node
"use strict";

/**
 * Self-contained verification for the Phase 0.4 MCP security-isolation harness.
 *
 * This script proves security-isolation.js behaves correctly on BOTH paths:
 *
 *   1. FAIL path — against a server that exhibits the CURRENT production
 *      behavior (DCR returns SPA HTML, no OAuth flow), the harness must exit 1
 *      with a focused violation (S0: OAuth flow did not complete).
 *   2. PASS path — against a server that implements fail-closed token
 *      validation, grant enforcement, and concurrency isolation, the harness
 *      must exit 0.
 *
 * It starts the verification-only mock server (mock/lifecycle-server.js) as a
 * child process, runs the harness (security-isolation.js) as a child process
 * against each endpoint, asserts the expected exit codes, and cleans up the
 * mock server.
 *
 * This is a test harness for the harness; it is not a release artifact and
 * does not touch production.
 *
 * Run:  node mcp-acceptance/verify-security-isolation.js
 * Exit: 0 if both paths behave as expected, 1 otherwise.
 */

const { spawn, execFile } = require("node:child_process");
const path = require("node:path");

const HERE = __dirname;
const MOCK = path.join(HERE, "mock", "lifecycle-server.js");
const HARNESS = path.join(HERE, "security-isolation.js");

function flagValue(argv, name, fallback) {
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === `--${name}`) return argv[i + 1];
    if (arg.startsWith(`--${name}=`)) return arg.slice(name.length + 3);
  }
  const envVal = process.env[name.toUpperCase()];
  return envVal !== undefined && envVal !== "" ? envVal : fallback;
}

const PORT = Number(flagValue(process.argv.slice(2), "port", process.env.MOCK_PORT || 4003));
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${PORT + 1}`;

function log(msg) {
  console.log(`[verify-security-isolation] ${msg}`);
}

function runHarness(url, issuer) {
  return new Promise((resolve) => {
    execFile(
      process.execPath,
      [HARNESS, "--url", url, "--issuer", issuer, "--timeout-ms", "5000"],
      { timeout: 20000 },
      (error, stdout, stderr) => {
        const exitCode =
          error === null ? 0 : typeof error.code === "number" ? error.code : -1;
        resolve({ exitCode, stdout, stderr });
      }
    );
  });
}

async function waitForServer(url, timeoutMs = 10000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
      void res.status;
      await res.arrayBuffer();
      return true;
    } catch {
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  return false;
}

function startMock(world) {
  return new Promise((resolve) => {
    const mock = spawn(process.execPath, [MOCK], {
      env: { ...process.env, MOCK_PORT: String(PORT), MOCK_WORLD: world },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let mockOutput = "";
    mock.stdout.on("data", (d) => {
      mockOutput += d.toString();
    });
    mock.stderr.on("data", (d) => {
      mockOutput += d.toString();
    });
    resolve({ mock, getOutput: () => mockOutput });
  });
}

async function main() {
  let allPassed = true;
  const check = (label, ok) => {
    log(`  ${label} -> ${ok ? "OK" : "MISMATCH"}`);
    if (!ok) allPassed = false;
  };

  // 1. FAIL path: current-production behavior -> harness must exit 1.
  log("FAIL path: harness vs current-production behavior (expect exit 1)");
  const { mock: mockFail, getOutput: getFailOutput } = await startMock("current");
  const upFail = await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`);
  if (!upFail) {
    log("ERROR: mock server (current) did not become ready");
    log(getFailOutput());
    mockFail.kill("SIGTERM");
    return 1;
  }
  const fail = await runHarness(`${MCP_BASE}/mcp`, ISSUER_BASE);
  check(`harness exit code: ${fail.exitCode} (expected 1)`, fail.exitCode === 1);
  check(
    "violation S0 (OAuth flow) present",
    fail.stdout.includes("S0:")
  );
  mockFail.kill("SIGTERM");
  await new Promise((r) => setTimeout(r, 200));

  // 2. PASS path: compliant behavior -> harness must exit 0.
  log("PASS path: harness vs compliant security/isolation server (expect exit 0)");
  const { mock: mockPass, getOutput: getPassOutput } = await startMock("compliant");
  const upPass = await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`);
  if (!upPass) {
    log("ERROR: mock server (compliant) did not become ready");
    log(getPassOutput());
    mockPass.kill("SIGTERM");
    return 1;
  }
  const pass = await runHarness(`${MCP_BASE}/mcp`, ISSUER_BASE);
  check(`harness exit code: ${pass.exitCode} (expected 0)`, pass.exitCode === 0);
  check("S1 passes", pass.stdout.includes("S1: PASS"));
  check("S2 passes", pass.stdout.includes("S2: PASS"));
  check("S3 passes", pass.stdout.includes("S3: PASS"));
  check("S4 passes", pass.stdout.includes("S4: PASS"));
  check("S5 passes", pass.stdout.includes("S5: PASS"));
  check("S6 passes", pass.stdout.includes("S6: PASS"));
  check("S7 passes", pass.stdout.includes("S7: PASS"));
  check("S8 passes", pass.stdout.includes("S8: PASS"));
  check("S9 passes", pass.stdout.includes("S9: PASS"));
  mockPass.kill("SIGTERM");
  await new Promise((r) => setTimeout(r, 200));

  log("");
  if (allPassed) {
    log("VERIFY PASS: security-isolation harness exits 1 on current-production behavior and 0 on compliant behavior.");
    return 0;
  }
  log("VERIFY FAIL: security-isolation harness behavior did not match expectations.");
  return 1;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[verify-security-isolation] UNEXPECTED ERROR: ${err && err.message ? err.message : String(err)}`);
    if (err && err.stack) console.error(err.stack);
    process.exitCode = 1;
  });

"use strict";

/**
 * Shared helpers for the Phase 0.3 (oauth-lifecycle) and Phase 0.4
 * (security-isolation) acceptance harnesses.
 *
 * This module is a pure HTTP client. It does NOT launch or depend on the
 * slice1-lab binaries, and it does NOT treat the lab binary as a release
 * artifact. It reuses the slice1-lab fixture shapes:
 *   - the DCR request shape (slice1-lab/negative_tests.py fresh_dcr,
 *     slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata);
 *   - the standard access-token claim contract (slice1-lab/src/jwt.rs
 *     AccessClaims: iss, numeric sub, aud, exp, iat, client_id, scope, jti,
 *     amr);
 *   - the scope catalog (slice1-lab/src/common.rs SCOPE_CATALOG);
 *   - the negative-token / fail-closed cases (slice1-lab/negative_tests.py
 *     cases 3-9, slice1-lab/PROOF.md P7).
 *
 * It owns its own production-facing configuration, lifecycle, reporting, and
 * cleanup: it is a pure HTTP client, starts no servers, and leaves no
 * processes behind.
 */

const crypto = require("node:crypto");

// ---------------------------------------------------------------------------
// Scope catalog (reused from slice1-lab/src/common.rs SCOPE_CATALOG)
// ---------------------------------------------------------------------------

const SCOPE_CATALOG = [
  "commoncal.calendar.metadata.read",
  "commoncal.availability.read",
  "commoncal.event.read.basic",
  "commoncal.event.read.details",
  "commoncal.event.create",
  "commoncal.event.update",
  "commoncal.event.delete",
  "commoncal.reminder.read",
  "commoncal.reminder.write",
];

// A scope deliberately outside the catalog (slice1-lab/src/common.rs EVIL_SCOPE).
const EVIL_SCOPE = "evil.unknown.scope";

// ---------------------------------------------------------------------------
// base64url helpers
// ---------------------------------------------------------------------------

function b64urlEncode(buf) {
  return Buffer.from(buf).toString("base64url");
}

function b64urlDecode(str) {
  return Buffer.from(str, "base64url");
}

function b64urlJson(obj) {
  return b64urlEncode(JSON.stringify(obj));
}

// ---------------------------------------------------------------------------
// PKCE S256
// ---------------------------------------------------------------------------

/**
 * Compute the S256 code challenge for a verifier (RFC 7636).
 */
function s256Challenge(verifier) {
  return b64urlEncode(crypto.createHash("sha256").update(verifier).digest());
}

/**
 * Generate a random PKCE code verifier (43-128 chars, RFC 7636).
 */
function generateVerifier() {
  return b64urlEncode(crypto.randomBytes(48));
}

// ---------------------------------------------------------------------------
// JWT helpers (decode only; no signature verification)
// ---------------------------------------------------------------------------

/**
 * Decode a JWT payload (no signature verification). Returns the claims object
 * or null.
 */
function decodeJwtPayload(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[1]).toString("utf8"));
  } catch {
    return null;
  }
}

/**
 * Decode a JWT header (no signature verification). Returns the header object
 * or null.
 */
function decodeJwtHeader(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[0]).toString("utf8"));
  } catch {
    return null;
  }
}

/**
 * Tamper a JWT's payload (re-encode with modified claims) without re-signing.
 * The signature becomes invalid, but the point is that validation fails closed.
 */
function tamperJwtPayload(jwt, claimOverrides) {
  const parts = jwt.split(".");
  if (parts.length !== 3) throw new Error("not a 3-part JWT");
  const claims = decodeJwtPayload(jwt);
  if (!claims) throw new Error("cannot decode payload");
  Object.assign(claims, claimOverrides);
  return `${parts[0]}.${b64urlJson(claims)}.${parts[2]}`;
}

/**
 * Tamper a JWT's signature (replace with a random signature of the same length).
 */
function tamperJwtSignature(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) throw new Error("not a 3-part JWT");
  const sigBytes = b64urlDecode(parts[2]);
  const randomSig = b64urlEncode(crypto.randomBytes(sigBytes.length));
  return `${parts[0]}.${parts[1]}.${randomSig}`;
}

// ---------------------------------------------------------------------------
// HTTP helpers
// ---------------------------------------------------------------------------

/**
 * Perform one HTTP request and capture the full response deterministically.
 */
async function httpProbe(cfg, method, url, body, headers = {}) {
  const reqHeaders = { ...headers };
  let bodyString = null;
  if (body !== null && body !== undefined) {
    bodyString = typeof body === "string" ? body : JSON.stringify(body);
    if (!reqHeaders["Content-Type"] && !reqHeaders["content-type"]) {
      reqHeaders["Content-Type"] = "application/json";
    }
  }
  if (method === "POST" && !reqHeaders.Accept && !reqHeaders.accept) {
    reqHeaders.Accept = "application/json, text/event-stream";
  }

  let status;
  let respHeaders;
  let rawBody;
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), cfg.timeoutMs);
    let res;
    try {
      res = await fetch(url, {
        method,
        headers: reqHeaders,
        body: bodyString,
        signal: controller.signal,
        redirect: "manual",
      });
    } finally {
      clearTimeout(timer);
    }
    status = res.status;
    respHeaders = normalizeHeaders(res.headers);
    rawBody = await res.text();
  } catch (err) {
    throw new Error(`network failure contacting ${url}: ${err.message}`);
  }

  let bodyJson = null;
  let bodyJsonParseError = null;
  try {
    bodyJson = JSON.parse(rawBody);
  } catch (err) {
    bodyJsonParseError = err.message;
  }

  return {
    status,
    headers: respHeaders,
    bodyRaw: rawBody,
    bodyJson,
    bodyJsonParseError,
  };
}

/**
 * Normalize response headers into a plain object, dropping volatile /
 * hop-by-hop headers so the recorded response is deterministic.
 */
function normalizeHeaders(headers) {
  const skip = new Set([
    "date",
    "x-request-id",
    "set-cookie",
    "transfer-encoding",
    "connection",
    "keep-alive",
  ]);
  const out = {};
  for (const [key, value] of headers.entries()) {
    const k = key.toLowerCase();
    if (skip.has(k)) continue;
    if (k in out) {
      out[k] = [].concat(out[k], value);
    } else {
      out[k] = value;
    }
  }
  return out;
}

function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

// ---------------------------------------------------------------------------
// OAuth flow (DCR + Authorization Code + S256 PKCE + token exchange)
// ---------------------------------------------------------------------------

/**
 * Register a client through DCR (RFC 7591) using the supported OpenCode
 * loopback redirect shape. Mirrors the lab's DCR policy
 * (slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @returns {Promise<{status: number, body: object}>}
 */
async function dcrRegister(cfg, issuer, redirect) {
  const body = {
    client_name: "commoncal-mcp-acceptance",
    redirect_uris: [redirect],
    grant_types: ["authorization_code", "refresh_token"],
    response_types: ["code"],
    token_endpoint_auth_method: "none",
    scope: SCOPE_CATALOG.join(" "),
  };
  const url = `${issuer.replace(/\/$/, "")}/register`;
  const resp = await httpProbe(cfg, "POST", url, body);
  return resp;
}

/**
 * Drive the Authorization Code flow with S256 PKCE. Returns the authorization
 * code and state from the redirect.
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} clientId  The DCR client id.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @param {string} scope  The requested scope.
 * @param {string} verifier  The PKCE code verifier.
 * @returns {Promise<{code: string|null, state: string|null, resp: object}>}
 */
async function authorize(cfg, issuer, clientId, redirect, scope, verifier) {
  const challenge = s256Challenge(verifier);
  const state = crypto.randomBytes(16).toString("hex");
  const params = new URLSearchParams({
    response_type: "code",
    client_id: clientId,
    redirect_uri: redirect,
    scope,
    state,
    code_challenge: challenge,
    code_challenge_method: "S256",
  });
  const url = `${issuer.replace(/\/$/, "")}/authorize?${params.toString()}`;
  const resp = await httpProbe(cfg, "GET", url, null);

  // Extract the code and state from the redirect Location header.
  let code = null;
  let returnedState = null;
  const location = resp.headers["location"];
  if (location) {
    try {
      const locUrl = new URL(location);
      code = locUrl.searchParams.get("code");
      returnedState = locUrl.searchParams.get("state");
    } catch {
      // Location is not a valid URL; leave code/state null.
    }
  }
  return { code, state: returnedState, resp };
}

/**
 * Exchange an authorization code for a token (Authorization Code + S256 PKCE).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} code  The authorization code.
 * @param {string} clientId  The DCR client id.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @param {string} verifier  The PKCE code verifier.
 * @returns {Promise<{status: number, body: object}>}
 */
async function tokenExchange(cfg, issuer, code, clientId, redirect, verifier) {
  const params = new URLSearchParams({
    grant_type: "authorization_code",
    code,
    redirect_uri: redirect,
    client_id: clientId,
    code_verifier: verifier,
  });
  const url = `${issuer.replace(/\/$/, "")}/token`;
  const resp = await httpProbe(cfg, "POST", url, params.toString(), {
    "Content-Type": "application/x-www-form-urlencoded",
  });
  return resp;
}

/**
 * Run the full OAuth flow: DCR + Authorization Code + S256 PKCE + token
 * exchange. Returns the access token and the full flow record.
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @returns {Promise<{accessToken: string|null, clientId: string|null, record: object}>}
 */
async function runOAuthFlow(cfg, issuer, redirect) {
  const record = {
    dcr: null,
    authorize: null,
    token: null,
  };

  // 1. DCR.
  const dcrResp = await dcrRegister(cfg, issuer, redirect);
  record.dcr = dcrResp;
  const clientId = dcrResp.bodyJson && dcrResp.bodyJson.client_id;
  if (!clientId) {
    return { accessToken: null, clientId: null, record };
  }

  // 2. Authorization Code + S256 PKCE.
  const verifier = generateVerifier();
  const scope = SCOPE_CATALOG.join(" ");
  const authResult = await authorize(cfg, issuer, clientId, redirect, scope, verifier);
  record.authorize = authResult;
  if (!authResult.code) {
    return { accessToken: null, clientId, record };
  }

  // 3. Token exchange.
  const tokenResp = await tokenExchange(cfg, issuer, authResult.code, clientId, redirect, verifier);
  record.token = tokenResp;
  const accessToken = tokenResp.bodyJson && tokenResp.bodyJson.access_token;

  return { accessToken, clientId, record };
}

// ---------------------------------------------------------------------------
// MCP calls
// ---------------------------------------------------------------------------

/**
 * Send a JSON-RPC request to the MCP endpoint.
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} mcpUrl  The MCP endpoint URL.
 * @param {string} method  The JSON-RPC method.
 * @param {object} params  The JSON-RPC params.
 * @param {number} id  The JSON-RPC id.
 * @param {string|null} accessToken  The Bearer access token (or null).
 * @returns {Promise<object>} The response record.
 */
async function mcpCall(cfg, mcpUrl, method, params, id, accessToken) {
  const body = {
    jsonrpc: "2.0",
    id,
    method,
    params,
  };
  const headers = {};
  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`;
  }
  return httpProbe(cfg, "POST", mcpUrl, body, headers);
}

/**
 * Send a JSON-RPC notification to the MCP endpoint (no id expected).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} mcpUrl  The MCP endpoint URL.
 * @param {string} method  The JSON-RPC method.
 * @param {object} params  The JSON-RPC params.
 * @param {string|null} accessToken  The Bearer access token (or null).
 * @returns {Promise<object>} The response record.
 */
async function mcpNotify(cfg, mcpUrl, method, params, accessToken) {
  const body = {
    jsonrpc: "2.0",
    method,
    params,
  };
  const headers = {};
  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`;
  }
  return httpProbe(cfg, "POST", mcpUrl, body, headers);
}

// ---------------------------------------------------------------------------
// Deterministic JSON
// ---------------------------------------------------------------------------

/**
 * Serialize a value to deterministic JSON (object keys sorted recursively).
 */
function deterministicStringify(value) {
  function sort(value) {
    if (Array.isArray(value)) return value.map(sort);
    if (isPlainObject(value)) {
      const out = {};
      for (const key of Object.keys(value).sort()) {
        out[key] = sort(value[key]);
      }
      return out;
    }
    return value;
  }
  return JSON.stringify(sort(value), null, 2);
}

module.exports = {
  SCOPE_CATALOG,
  EVIL_SCOPE,
  b64urlEncode,
  b64urlDecode,
  b64urlJson,
  s256Challenge,
  generateVerifier,
  decodeJwtPayload,
  decodeJwtHeader,
  tamperJwtPayload,
  tamperJwtSignature,
  httpProbe,
  normalizeHeaders,
  isPlainObject,
  dcrRegister,
  authorize,
  tokenExchange,
  runOAuthFlow,
  mcpCall,
  mcpNotify,
  deterministicStringify,
};

#!/usr/bin/env node
"use strict";

/**
 * Verification-only mock MCP + OAuth server for the Phase 0.3 (oauth-lifecycle)
 * and Phase 0.4 (security-isolation) acceptance harnesses.
 *
 * This is NOT a release artifact and NOT the production component. It exists
 * solely to exercise the harnesses' PASS and FAIL paths deterministically.
 *
 * The mock mirrors production's two-host topology and is driven by a single
 * world selector so its behavior is order-independent (a real OAuth client
 * discovers before it ever calls the MCP endpoint, so the world cannot be
 * inferred from the first MCP probe):
 *
 *   MOCK_WORLD=compliant (default) — the TARGET state:
 *     MCP host (MOCK_PORT, default 4001):
 *       GET  /.well-known/oauth-protected-resource
 *            -> RFC 9728 protected-resource metadata (valid JSON), naming the
 *               issuer host
 *       POST /mcp
 *            -> full authenticated MCP lifecycle (initialize,
 *               notifications/initialized, tools/list, tools/call
 *               calendar_list) gated by Bearer JWT validation + live grant
 *     Issuer host (MOCK_ISSUER_PORT, default MOCK_PORT + 1):
 *       GET  /.well-known/oauth-authorization-server
 *            -> RFC 8414 authorization-server metadata (valid JSON with
 *               authorization, token, registration, and JWKS endpoints)
 *       GET  /.well-known/openid-configuration
 *            -> CommonCal SPA HTML (mirrors the verified current state of
 *               cal.hajnal.space, which falls through to the SPA ingress)
 *       POST /register  -> DCR (RFC 7591) client registration
 *       GET  /authorize -> Authorization Code flow with S256 PKCE (auto-approves
 *                          login and consent, redirects back with the code)
 *       POST /token     -> Token exchange (Authorization Code + S256 PKCE)
 *       GET  /jwks      -> JWKS document (public key only)
 *
 *   MOCK_WORLD=current — the CURRENT production state:
 *     MCP host:
 *       GET  /.well-known/oauth-protected-resource
 *            -> valid JSON (production serves this document correctly)
 *       POST /mcp
 *            -> the CURRENT production gateway: only tools/list and tools/call
 *               are recognized; initialize (and everything else) is HTTP 400
 *               with JSON-RPC -32601 and no WWW-Authenticate header
 *               (mcp-server/src/gateway.rs)
 *     Issuer host:
 *       every route -> CommonCal SPA HTML (the authorization service is not
 *          deployed; the advertised issuer host is handled by core's "/"
 *          ingress and falls through to the SPA — docs/MCP-PRODUCTION-FIX-PLAN.md)
 *
 * The world is fixed at startup (MOCK_WORLD), so discovery, DCR, authorization,
 * token exchange, and the MCP lifecycle all agree regardless of request order.
 *
 * Run:  node mcp-acceptance/mock/lifecycle-server.js
 * Env:  MOCK_PORT (default 4001), MOCK_ISSUER_PORT (default MOCK_PORT + 1),
 *       MOCK_WORLD (default "compliant"; "current" mirrors production today)
 */

const http = require("node:http");
const {
  MockOAuthProvider,
  SCOPE_CATALOG,
  decodeJwtPayload,
} = require("./oauth-provider");

const PORT = Number(process.env.MOCK_PORT || 4001);
const ISSUER_PORT = Number(process.env.MOCK_ISSUER_PORT || PORT + 1);
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${ISSUER_PORT}`;
const RESOURCE_URL = `${MCP_BASE}/mcp`;
const LOOPBACK_REDIRECT = "http://127.0.0.1:8765/callback";
const WORLD = (process.env.MOCK_WORLD || "compliant").toLowerCase();
const COMPLIANT = WORLD !== "current";

const SPA_HTML =
  '<!doctype html><html><head><meta charset="utf-8"><title>CommonCal</title></head><body><div id="root"></div><script src="/static/js/main.js"></script></body></html>';

// The mock OAuth provider (DCR + Authorization Code + S256 PKCE + token
// exchange + JWKS + token validation + grants).
const provider = new MockOAuthProvider({
  issuer: ISSUER_BASE,
  resource: RESOURCE_URL,
  redirect: LOOPBACK_REDIRECT,
});

// Per-subject calendar data for the mock. Each subject has a distinct set of
// calendars so the concurrency isolation test can verify that two clients
// cannot observe each other's calendars.
const SUBJECT_CALENDARS = {
  "1": [
    { id: 101, name: "Alice Work", color: "#ff0000", access: "full" },
    { id: 102, name: "Alice Personal", color: "#00ff00", access: "read" },
  ],
  "2": [
    { id: 201, name: "Bob Work", color: "#0000ff", access: "full" },
    { id: 202, name: "Bob Personal", color: "#ff00ff", access: "read" },
